card.content:
{% set n = states('sensor.ai_watchdog_problems') | int(0) %}
<ha-alert alert-type="warning" title="{{ n }} problem{{ 's' if n != 1 }} found by the watchdog">Each one has an AI analysis and a proposed fix.</ha-alert>
{% for i in state_attr('sensor.ai_watchdog_problems', 'items') or [] %}
**{{ '🔴' if i.severity == 'critical' else '🟠' }} {{ i.name }}**
{{ i.summary }}
<a href="{{ i.url }}" target="_blank"><b>View analysis and fix →</b></a>

{% endfor %}
<a href="{{ state_attr('sensor.ai_watchdog_problems', 'index_url') }}" target="_blank">All AI analyses</a> · home network / VPN only
